function toSeedRows(raw: RawRow[]): SeedRow[] {
  return raw.map(([ticker, date, closing_price]) => ({ ticker, date, closing_price }));
}

export const SEED_ROWS: SeedRow[] = toSeedRows(RAW_ROWS);

export function generateSeedRows(): SeedRow[] {
  return SEED_ROWS;
}
